package dev.luna.backend;
import com.google.gson.*;import java.net.*;import java.net.http.*;import java.io.*;import java.time.Duration;import java.util.*;
import static dev.luna.backend.JsonData.*;
/** Local data-only inference. No subprocesses, script engines, downloads, or cloud fallback. */
public final class OllamaClient {
 public record Generation(String brief,JsonObject plan,JsonObject compiled,JsonArray usage,String model){}
 private final HttpClient http=LoopbackHttp.create();
 public static URI endpoint(String url){URI u=URI.create(url);require("http".equals(u.getScheme())&&u.getHost()!=null&&Set.of("127.0.0.1","localhost","[::1]","::1").contains(u.getHost())&&"/api/chat".equals(u.getPath())&&u.getUserInfo()==null&&u.getQuery()==null&&u.getFragment()==null,"Only a loopback Ollama HTTP /api/chat endpoint is allowed");return u;}
 private JsonObject request(URI uri,JsonObject body)throws Exception {if(Thread.interrupted())throw new InterruptedException("Cancelled");var b=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(180));if(body==null)b.GET();else b.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(GSON.toJson(body)));HttpResponse<InputStream> response;
  try{response=http.send(b.build(),HttpResponse.BodyHandlers.ofInputStream());}catch(java.net.ConnectException e){throw new IOException("Cannot reach local Ollama. Open your installed Ollama app; the mod does not launch external programs.");}
  try(InputStream in=response.body()){byte[] bytes=in.readNBytes(2_000_001);require(bytes.length<=2_000_000,"Ollama response exceeds limit");if(response.statusCode()!=200)throw new IOException("Ollama HTTP "+response.statusCode()+": check the installed model and available memory");return JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}
 }
 private static boolean cloud(JsonObject j){String name=s(j,"name",s(j,"model",""));return j.has("remote_host")||j.has("remote_model")||name.matches("(?i).*[:\\-]cloud(?:$|:).*?");}
 public String choose(JsonObject config)throws Exception {URI chat=endpoint(s(config,"providerUrl","http://127.0.0.1:11434/api/chat"));JsonObject tags=request(chat.resolve("/api/tags"),null);require(tags.has("models")&&tags.get("models").isJsonArray()&&tags.getAsJsonArray("models").size()<=500,"Invalid Ollama model catalog");List<JsonObject> models=new ArrayList<>();for(JsonElement el:tags.getAsJsonArray("models")){JsonObject m=el.getAsJsonObject();String name=s(m,"name",s(m,"model",""));if(!name.isBlank()&&!cloud(m)&&!name.matches("(?i).*(embed|nomic|bge-|rerank).*")){m.addProperty("name",name);models.add(m);}}
  String selected=s(config,"modelId","");models.sort(Comparator.comparingDouble(OllamaClient::score).thenComparing(m->s(m,"name","")));if(!selected.isBlank()){models.removeIf(m->!s(m,"name","").equals(selected));require(!models.isEmpty(),"Selected model is not installed locally or is a cloud/embedding model");}
  for(JsonObject m:models.subList(0,Math.min(32,models.size()))){String name=s(m,"name","");JsonObject body=o();body.addProperty("model",name);JsonObject details=request(chat.resolve("/api/show"),body);JsonArray caps=details.getAsJsonArray("capabilities");if(!cloud(details)&&caps!=null&&caps.contains(new JsonPrimitive("completion")))return name;}
  throw new IllegalArgumentException("No installed local completion model found. Install a local chat model in Ollama; the mod never downloads models.");
 }
 private static double score(JsonObject m){double size=m.has("size")?m.get("size").getAsDouble()/1e9:0;String name=s(m,"name","").toLowerCase(Locale.ROOT);return (size>=2&&size<=8?0:20)+(size>8?size:0)+(size<2?10:0)+(name.contains("qwen")?(name.contains("coder")?0:1):name.matches(".*(llama|gemma|mistral).*")?3:5);}
 private String chat(JsonObject config,String model,JsonArray messages,boolean json,JsonArray usage)throws Exception {JsonObject body=o();body.addProperty("model",model);body.add("messages",messages);body.addProperty("stream",false);if(json)body.addProperty("format","json");JsonObject options=o();options.addProperty("num_predict",json?8192:1024);options.addProperty("num_ctx",32768);body.add("options",options);JsonObject response=request(endpoint(s(config,"providerUrl","")),body);if(response.has("prompt_eval_count")&&response.has("eval_count")){JsonObject u=o();u.addProperty("provider","ollama");u.addProperty("model",model);u.add("prompt_tokens",response.get("prompt_eval_count"));u.add("completion_tokens",response.get("eval_count"));usage.add(u);}require(response.has("message")&&response.get("message").isJsonObject(),"Ollama returned no message");String text=s(response.getAsJsonObject("message"),"content","");require(!text.isBlank()&&text.length()<2_000_000,"Ollama returned empty or excessive output");return text;}
 private static JsonObject message(String role,String content){JsonObject m=o();m.addProperty("role",role);m.addProperty("content",content);return m;}
 public Generation generate(JsonObject config,JsonObject input,JsonObject registry,int[] dimensions)throws Exception {String model=choose(config);JsonArray usage=a(),briefMessages=a();briefMessages.add(message("system","Write a concise Minecraft architectural brief: silhouette, proportions, palette, entrance, usable interior, lighting and landscaping. Return text, not code."));briefMessages.add(message("user",GSON.toJson(input)));String brief=chat(config,model,briefMessages,false,usage);StringBuilder blocks=new StringBuilder();for(var e:registry.entrySet())if(!b(e.getValue().getAsJsonObject(),"blockEntity"))blocks.append(e.getKey()).append(',');
  String schema="Return ONLY JSON data: {version:1,title:string,palette:{key:\"minecraft:block_id[optional=state]\"},operations:[{id:string,type:\"fill\"|\"floor\"|\"wall\"|\"hollow\"|\"pillar\"|\"stairs\"|\"roof\"|\"path\"|\"place\",material:paletteKey,group:string,depends?:[id],replace?:boolean,...}]}. Fill/floor/wall/hollow use inclusive from:[x,y,z],to:[x,y,z]. Pillar: at,height. Stairs: at,length,width rises +z. Roof: at,width,length, connected two-block-thick gable along z. Path: points. Place: at. Integer relative bounds -128..128; max 60000 positions and selected dimensions. Hollow includes all six faces; openings use explicit air, replace:true. Components need connected supports. No block entities, fluids, waterlogging, fire, TNT, portals, commands or executable code. Compose windows, arches, doorways, furniture and repeated components using supported primitives. Valid registry IDs: "+blocks;
  JsonArray messages=a();messages.add(message("system",schema));JsonObject request=o();request.add("input",input);request.addProperty("brief",brief);messages.add(message("user",GSON.toJson(request)));Exception last=null;
  for(int attempt=0;attempt<3;attempt++){String raw=chat(config,model,messages,true,usage).replaceFirst("^```(?:json)?\\s*","").replaceFirst("\\s*```$","");messages.add(message("assistant",raw));try{JsonObject plan=JsonParser.parseString(raw).getAsJsonObject();JsonObject compiled=PlanCompiler.compile(plan,registry,dimensions);return new Generation(brief,plan,compiled,usage,model);}catch(Exception e){last=e;messages.add(message("user","Repair the JSON plan using this validation error: "+e.getMessage()));}}
  throw new IOException("Plan validation failed after bounded repairs: "+(last==null?"invalid JSON":last.getMessage()));
 }
}
